// 5x5 monitoring grid over Lahore (about 14 km cells)
var cells = [];
var lats = [];
var lons = [];
for (var r = 0; r < 5; r++) {
  for (var c = 0; c < 5; c++) {
    var lat = Math.round((31.25 + r * 0.125) * 1000) / 1000;
    var lon = Math.round((74.0 + c * 0.15) * 1000) / 1000;
    cells.push({ id: 'L' + r + c, lat: lat, lon: lon });
    lats.push(lat);
    lons.push(lon);
  }
}
return [{ json: { cells: cells, lats: lats.join(','), lons: lons.join(',') } }];

var run = $('Run Config').first().json;
var runAt = run.run_at;
var runId = run.run_id;
var secret = run.firms_map_key || '';
var out = [];
var nowMs = Date.now();
var R = 6371;

function rad(d) { return d * Math.PI / 180; }
function dist(a, b, c, d) {
  var dLat = rad(c - a);
  var dLon = rad(d - b);
  var x = Math.sin(dLat / 2) * Math.sin(dLat / 2) + Math.cos(rad(a)) * Math.cos(rad(c)) * Math.sin(dLon / 2) * Math.sin(dLon / 2);
  return 2 * R * Math.asin(Math.sqrt(x));
}
function bearing(a, b, c, d) {
  var y = Math.sin(rad(d - b)) * Math.cos(rad(c));
  var x = Math.cos(rad(a)) * Math.sin(rad(c)) - Math.sin(rad(a)) * Math.cos(rad(c)) * Math.cos(rad(d - b));
  return (Math.atan2(y, x) * 180 / Math.PI + 360) % 360;
}
function angDiff(a, b) { var d = Math.abs(a - b) % 360; return d > 180 ? 360 - d : d; }
function num(v) {
  if (v === null || v === undefined || v === '') return null;
  var n = Number(v);
  return isFinite(n) ? n : null;
}
function r1(v) { return v === null ? null : Math.round(v * 10) / 10; }
function safe(name) {
  try { return $(name).all().map(function (i) { return i.json; }); } catch (e) { return []; }
}
function clean(msg) {
  var s = String(msg || '');
  if (secret) s = s.split(secret).join('***');
  return s.substring(0, 300);
}
function log(source, status, records, message) {
  out.push({ json: { kind: 'log', run_at: runAt, run_id: runId, source: source, status: status, records: records, message: message } });
}
function sevOf(p) { return p >= 150 ? 'severe' : p >= 100 ? 'high' : p >= 55 ? 'elevated' : 'normal'; }
function downgrade(c) { return c === 'high' ? 'medium' : 'low'; }

// ---------- 1. Air quality + weather (validated) ----------
var cells = $('Build Grid').first().json.cells;
var aq = safe('Fetch Air Quality');
var wx = safe('Fetch Weather');
var obs = [];
var removed = 0;
var stale = 0;
for (var i = 0; i < cells.length; i++) {
  var a = aq[i] && aq[i].current ? aq[i].current : null;
  var w = wx[i] && wx[i].current ? wx[i].current : null;
  if (!a) continue;
  var pm25 = num(a.pm2_5);
  if (pm25 === null || pm25 < 0 || pm25 > 1500) { removed++; continue; }
  var t = Date.parse(a.time + ':00Z');
  if (!isFinite(t)) { removed++; continue; }
  if ((nowMs - t) / 3600000 > 4) stale++;
  obs.push({
    cell_id: cells[i].id, lat: cells[i].lat, lon: cells[i].lon, pm25: pm25,
    pm10: num(a.pm10), no2: num(a.nitrogen_dioxide), aod: num(a.aerosol_optical_depth),
    temp_c: w ? num(w.temperature_2m) : null, humidity: w ? num(w.relative_humidity_2m) : null,
    wind_speed: w ? num(w.wind_speed_10m) : null, wind_dir: w ? num(w.wind_direction_10m) : null,
    observed_at: new Date(t).toISOString()
  });
}
if (obs.length === 0) {
  var aqErr = aq.length && aq[0].error ? clean(JSON.stringify(aq[0].error)) : 'No valid air quality records returned';
  log('open-meteo-cams', 'failed', 0, aqErr);
} else if (stale === obs.length) {
  log('open-meteo-cams', 'stale', obs.length, 'All records older than 4 hours; not treated as current. Removed invalid: ' + removed);
} else {
  log('open-meteo-cams', 'ok', obs.length, 'Valid cells: ' + obs.length + ', removed invalid: ' + removed);
}
var wxCount = 0;
for (var k = 0; k < wx.length; k++) { if (wx[k] && wx[k].current) wxCount++; }
log('open-meteo-weather', wxCount > 0 ? 'ok' : 'failed', wxCount, wxCount > 0 ? 'Weather cells: ' + wxCount : 'No weather records returned (attribution has no wind data)');
var aqFresh = obs.length > 0 && stale < obs.length;

// ---------- 2. Fires (FIRMS) ----------
var frRaw = safe('Fetch Fires');
var txt = frRaw.length && typeof frRaw[0].data === 'string' ? frRaw[0].data : '';
var fires = [];
if (txt.indexOf('latitude') !== 0) {
  var frMsg = frRaw.length && frRaw[0].error ? clean(JSON.stringify(frRaw[0].error)) : clean(txt || 'Empty response');
  log('nasa-firms', 'failed', 0, frMsg);
} else {
  var lines = txt.trim().split(/\r?\n/);
  var hdr = lines[0].split(',');
  var ix = {};
  for (var h = 0; h < hdr.length; h++) ix[hdr[h].trim()] = h;
  for (var l = 1; l < lines.length; l++) {
    var p = lines[l].split(',');
    var flat = num(p[ix.latitude]);
    var flon = num(p[ix.longitude]);
    if (flat === null || flon === null) continue;
    var conf = String(p[ix.confidence] || '').trim().toLowerCase();
    if (conf === 'l' || conf === 'low') continue;
    var hhmm = String(p[ix.acq_time] || '0000');
    while (hhmm.length < 4) hhmm = '0' + hhmm;
    var ft = Date.parse(p[ix.acq_date] + 'T' + hhmm.substring(0, 2) + ':' + hhmm.substring(2, 4) + ':00Z');
    if (!isFinite(ft) || (nowMs - ft) > 48 * 3600000) continue;
    fires.push({
      fire_key: flat + '_' + flon + '_' + p[ix.acq_date] + '_' + hhmm,
      acq_time: new Date(ft).toISOString(), lat: flat, lon: flon,
      frp: num(p[ix.frp]) || 0, confidence: conf, satellite: String(p[ix.satellite] || '').trim(), ageH: (nowMs - ft) / 3600000
    });
  }
  log('nasa-firms', 'ok', fires.length, 'Active fire detections (last 48h, non-low confidence): ' + fires.length);
}
var recent = fires.filter(function (f) { return f.ageH <= 36; }).slice(0, 3000);
var clusters = [];
for (var q = 0; q < recent.length; q++) {
  var f = recent[q];
  var hit = null;
  for (var cI = 0; cI < clusters.length; cI++) {
    if (dist(clusters[cI].lat, clusters[cI].lon, f.lat, f.lon) <= 3) { hit = clusters[cI]; break; }
  }
  if (hit) {
    hit.n++; hit.frp += f.frp;
    hit.lat = (hit.lat * (hit.n - 1) + f.lat) / hit.n;
    hit.lon = (hit.lon * (hit.n - 1) + f.lon) / hit.n;
  } else { clusters.push({ lat: f.lat, lon: f.lon, n: 1, frp: f.frp }); }
}
var storeFires = fires.slice().sort(function (x, y) { return y.frp - x.frp; }).slice(0, 400);
for (var sf = 0; sf < storeFires.length; sf++) {
  var s = storeFires[sf];
  out.push({ json: { kind: 'fire', fire_key: s.fire_key, acq_time: s.acq_time, lat: s.lat, lon: s.lon, frp: s.frp, confidence: s.confidence, satellite: s.satellite } });
}

// ---------- 3. Facilities (OSM) and ground sensors (OpenAQ) ----------
var fac = safe('Read Facilities').filter(function (x) { return num(x.lat) !== null && num(x.lon) !== null; });
var ground = [];
var seenG = {};
var gRows = safe('Read Ground Sensors');
for (var g = 0; g < gRows.length; g++) {
  var gr = gRows[g];
  if (gr.source !== 'openaq' || num(gr.pm25) === null || seenG[gr.cell_id]) continue;
  var gt = Date.parse(gr.observed_at);
  if (!isFinite(gt) || (nowMs - gt) > 3 * 3600000) continue;
  seenG[gr.cell_id] = true;
  ground.push({ lat: Number(gr.lat), lon: Number(gr.lon), pm25: Number(gr.pm25) });
}

// ---------- 4. Hotspots + rule-based attribution ----------
var sorted = obs.map(function (o) { return o.pm25; }).sort(function (x, y) { return x - y; });
var median = sorted.length ? sorted[Math.floor(sorted.length / 2)] : 0;
var month = new Date().getUTCMonth() + 1;
var burningSeason = [10, 11, 12, 4, 5].indexOf(month) !== -1;
var state = $getWorkflowStaticData('global');
state.alerts = state.alerts || {};
var hotspots = [];
if (aqFresh) {
  for (var o2 = 0; o2 < obs.length; o2++) {
    var ob = obs[o2];
    var sev = sevOf(ob.pm25);
    if (sev === 'normal') continue;
    if (!(ob.pm25 >= 100 || ob.pm25 >= 1.1 * median)) continue;
    var radius = ob.wind_speed !== null ? Math.min(80, Math.max(30, ob.wind_speed * 3.6 * 6)) : 40;
    var up = 0;
    var near = 0;
    var upClusters = 0;
    for (var fi = 0; fi < recent.length; fi++) {
      var fx = recent[fi];
      var d = dist(ob.lat, ob.lon, fx.lat, fx.lon);
      if (d <= 15) near++;
      if (ob.wind_dir !== null && d <= radius && angDiff(bearing(ob.lat, ob.lon, fx.lat, fx.lon), ob.wind_dir) <= 50) up++;
    }
    for (var ci = 0; ci < clusters.length; ci++) {
      var cl = clusters[ci];
      if (ob.wind_dir !== null && dist(ob.lat, ob.lon, cl.lat, cl.lon) <= radius && angDiff(bearing(ob.lat, ob.lon, cl.lat, cl.lon), ob.wind_dir) <= 50) upClusters++;
    }
    var nFac = 0;
    for (var fa = 0; fa < fac.length; fa++) {
      if (dist(ob.lat, ob.lon, Number(fac[fa].lat), Number(fac[fa].lon)) <= 5) nFac++;
    }
    var label = 'Undetermined (regional/transported smoke, traffic or other)';
    var conf = 'low';
    if (up >= 3 && burningSeason) { label = 'Likely crop burning'; conf = up >= 8 ? 'high' : 'medium'; }
    else if ((up >= 1 || near >= 1) && !(nFac >= 15 && up < 3)) { label = 'Possible crop/biomass burning'; conf = 'low'; }
    else if (nFac >= 5 && near === 0) { label = 'Possible industrial source'; conf = nFac >= 15 ? 'medium' : 'low'; }
    var gBest = null;
    var gDist = 999;
    for (var gi = 0; gi < ground.length; gi++) {
      var gd = dist(ob.lat, ob.lon, ground[gi].lat, ground[gi].lon);
      if (gd <= 15 && gd < gDist) { gDist = gd; gBest = ground[gi]; }
    }
    var agree = 'no sensor nearby';
    var gPm = null;
    if (gBest) {
      gPm = r1(gBest.pm25);
      var ratio = gBest.pm25 / ob.pm25;
      agree = ratio >= 0.6 && ratio <= 1.5 ? 'agrees' : (ratio > 1.5 ? 'ground higher' : 'ground lower');
      if (agree === 'ground lower') conf = downgrade(conf);
    }
    var score = (sev === 'severe' ? 60 : sev === 'high' ? 40 : 20) + Math.min(ob.pm25, 300) / 10 + Math.min(up, 20) * 1.5 + Math.min(nFac, 20) * 0.5 + (agree === 'agrees' ? 5 : 0);
    var ev = 'PM2.5 ' + r1(ob.pm25) + ' ug/m3 (regional median ' + r1(median) + '). ';
    ev += ob.wind_dir !== null ? ('Wind from ' + Math.round(ob.wind_dir) + ' deg at ' + r1(ob.wind_speed) + ' m/s. ') : 'No wind data. ';
    ev += up + ' fire detections (' + upClusters + ' clusters) upwind within ' + Math.round(radius) + ' km; ' + near + ' within 15 km. ';
    ev += nFac + ' mapped industrial/kiln sites within 5 km. ';
    if (ob.no2 !== null) ev += 'NO2 ' + r1(ob.no2) + ' ug/m3. ';
    ev += 'Ground sensor: ' + agree + (gPm !== null ? (' (' + gPm + ' ug/m3)') : '') + '. ';
    ev += burningSeason ? 'Burning season. ' : 'Outside main burning season. ';
    ev += 'Satellite/model estimate: confirm by field inspection.';
    var alerted = false;
    if ((sev === 'high' || sev === 'severe') && (!state.alerts[ob.cell_id] || nowMs - state.alerts[ob.cell_id] > 6 * 3600000)) {
      alerted = true;
      state.alerts[ob.cell_id] = nowMs;
    }
    hotspots.push({
      detected_at: runAt, run_id: runId, cell_id: ob.cell_id, lat: ob.lat, lon: ob.lon, pm25: r1(ob.pm25), severity: sev,
      priority_score: r1(score), attribution: label, attribution_confidence: conf, fires_upwind: up, fires_nearby: near,
      facilities_nearby: nFac, ground_pm25: gPm, ground_agreement: agree, evidence: ev, alerted: alerted
    });
  }
}
hotspots.sort(function (x, y) { return y.priority_score - x.priority_score; });
for (var hs = 0; hs < hotspots.length; hs++) { var row = hotspots[hs]; row.kind = 'hotspot'; out.push({ json: row }); }
log('detection', aqFresh ? 'ok' : 'skipped', hotspots.length, aqFresh ? ('Hotspots flagged: ' + hotspots.length + '; fire clusters: ' + clusters.length + '; facilities loaded: ' + fac.length + '; ground sensors: ' + ground.length) : 'No fresh air quality data, so no hotspots were produced');

// ---------- 5. Observations ----------
for (var ob2 = 0; ob2 < obs.length; ob2++) {
  var x2 = obs[ob2];
  out.push({ json: { kind: 'obs', observed_at: x2.observed_at, cell_id: x2.cell_id, lat: x2.lat, lon: x2.lon, pm25: x2.pm25, pm10: x2.pm10, no2: x2.no2, aod: x2.aod, temp_c: x2.temp_c, humidity: x2.humidity, wind_speed: x2.wind_speed, wind_dir: x2.wind_dir, source: 'open-meteo-cams' } });
}
return out;

var rows = $('Detect & Attribute').all().map(function (i) { return i.json; }).filter(function (j) { return j.kind === 'hotspot' && j.alerted === true; });
if (rows.length === 0) return [];
rows.sort(function (a, b) { return b.priority_score - a.priority_score; });
var top = rows.slice(0, 10);
var html = '<h2>Smoke hotspot alert (research prototype)</h2>';
html += '<p>' + rows.length + ' new high/severe hotspot(s) in the Lahore region. Ranked by priority. Estimates come from satellite/model data and must be confirmed by field inspection before any enforcement action.</p><ol>';
for (var i = 0; i < top.length; i++) {
  var t = top[i];
  html += '<li><b>' + t.severity.toUpperCase() + '</b> - PM2.5 ' + t.pm25 + ' ug/m3 at ' + t.lat + ', ' + t.lon + '<br>';
  html += 'Likely source: ' + t.attribution + ' (confidence: ' + t.attribution_confidence + ')<br>';
  html += '<small>' + t.evidence + '</small></li>';
}
html += '</ol>';
return [{ json: { subject: 'Smoke alert: ' + rows.length + ' new high-priority hotspot(s) near Lahore', html: html } }];
